&lt;/li&gt;
&lt;li style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;
&lt;p id=&quot;p-rc_e7c99a547c815c92-108&quot; data-path-to-node=&quot;18,1,0&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span data-path-to-node=&quot;18,1,0,0&quot;&gt;Identify new commercial categories and corridors with high recording potential&lt;/span&gt;&lt;span data-path-to-node=&quot;18,1,0,1&quot;&gt;&lt;sup class=&quot;superscript&quot;&gt;&lt;/sup&gt;&lt;/span&gt;&lt;span data-path-to-node=&quot;18,1,0,2&quot;&gt;.&lt;/span&gt; &lt;/span&gt;&lt;/p&gt;
