&lt;/ul&gt;
&lt;h3 data-path-to-node=&quot;19&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;strong data-path-to-node=&quot;19&quot; data-index-in-node=&quot;0&quot;&gt;3. Recording-Day Support&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul data-path-to-node=&quot;20&quot;&gt;
