&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Experience managing large or distributed QA/QC teams.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Strong knowledge of root-cause analysis, CAPA, FMEA, 8D, SPC, and quality management systems.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Strong analytical and problem-solving skills with a data-driven approach to quality.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Excellent stakeholder management and communication skills.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;A hands-on, high-ownership mindset — someone who is comfortable being on the floor, solving problems, and building processes rather than just managing them.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;&lt;strong&gt;Good to Have&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
